import React, { useState } from 'react';
import './TodoItem.css';

const TodoItem = ({ todo, onUpdateTodo, onDeleteTodo, onToggleTodo }) => {
  const [showDetails, setShowDetails] = useState(false);

  const getStatusColor = (status) => {
    switch (status) {
      case 'completed':
        return '#10b981';
      case 'in_progress':
        return '#3b82f6';
      case 'yet_to_start':
        return '#f59e0b';
      default:
        return '#6b7280';
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'completed':
        return '✅';
      case 'in_progress':
        return '⏳';
      case 'yet_to_start':
        return '⭕';
      default:
        return '❓';
    }
  };

  const getStatusLabel = (status) => {
    switch (status) {
      case 'completed':
        return 'Completed';
      case 'in_progress':
        return 'In Progress';
      case 'yet_to_start':
        return 'Yet to Start';
      default:
        return 'Unknown';
    }
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'high':
        return '#ef4444';
      case 'medium':
        return '#f59e0b';
      case 'low':
        return '#10b981';
      default:
        return '#6b7280';
    }
  };

  const getPriorityIcon = (priority) => {
    switch (priority) {
      case 'high':
        return '🔴';
      case 'medium':
        return '🟡';
      case 'low':
        return '🟢';
      default:
        return '⚪';
    }
  };

  const getCategoryEmoji = (category) => {
    const emojis = {
      work: '💼',
      personal: '📝',
      shopping: '🛒',
      health: '💪',
      general: '📌',
      other: '📦',
    };
    return emojis[category] || '📌';
  };

  const getRecurrenceLabel = (type) => {
    const labels = {
      daily: '🔄 Daily',
      weekly: '🔄 Weekly',
      monthly: '🔄 Monthly',
      none: '',
    };
    return labels[type] || '';
  };

  return (
    <div className={`todo-item ${todo.status === 'completed' ? 'completed' : ''}`}>
      <div className="todo-header">
        <div className="todo-status-selector">
          <select
            value={todo.status || 'yet_to_start'}
            onChange={(e) => onUpdateTodo(todo.id, { status: e.target.value })}
            className="status-dropdown"
            title="Change status"
          >
            <option value="yet_to_start">⭕ Yet to Start</option>
            <option value="in_progress">⏳ In Progress</option>
            <option value="completed">✅ Completed</option>
          </select>
        </div>

        <div className="todo-main">
          <div className="todo-title-row">
            <h4 className={`todo-title ${todo.status === 'completed' ? 'completed' : ''}`}>{todo.title}</h4>
            {todo.isRecurring && (
              <span className="recurring-badge">{getRecurrenceLabel(todo.recurrenceType)}</span>
            )}
          </div>
          {todo.description && <p className="todo-description">{todo.description}</p>}
        </div>

        <div className="todo-badges">
          <span
            className="badge priority-badge"
            style={{ borderLeft: `4px solid ${getPriorityColor(todo.priority)}` }}
            title={`Priority: ${todo.priority}`}
          >
            {getPriorityIcon(todo.priority)}
          </span>
          <span className="badge category-badge" title={`Category: ${todo.category}`}>
            {getCategoryEmoji(todo.category)}
          </span>
        </div>

        <div className="todo-actions">
          <button
            className={`btn-detail ${showDetails ? 'active' : ''}`}
            onClick={() => setShowDetails(!showDetails)}
            title="Show details"
          >
            ⋮
          </button>
          <button
            className="btn-delete"
            onClick={() => {
              if (window.confirm('Delete this todo?')) {
                onDeleteTodo(todo.id);
              }
            }}
            title="Delete todo"
          >
            🗑️
          </button>
        </div>
      </div>

      {showDetails && (
        <div className="todo-details">
          {todo.tags.length > 0 && (
            <div className="detail-row">
              <strong>Tags:</strong>
              <div className="tags">
                {todo.tags.map(tag => (
                  <span key={tag} className="tag-badge">{tag}</span>
                ))}
              </div>
            </div>
          )}

          <div className="detail-row">
            <strong>Created:</strong>
            <span>{new Date(todo.created_at).toLocaleDateString()}</span>
          </div>

          {todo.due_date && (
            <div className="detail-row">
              <strong>Due:</strong>
              <span>{new Date(todo.due_date).toLocaleDateString()}</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default TodoItem;
